using DiffMoM, LinearAlgebra

# FLOAT file-model attach-law coupon: two sheet pads, two box ports, a
# GNDREF=FLOAT component with two positive unpaired SMDP pins and a
# supplied 2-port SPARAM response (same (pin,common) attach path as
# staged file models).
records(tokens)=SonnetRecord(1,String.(tokens))
left=SonnetPolygon(:sheet,0,-1,1,[0.0 0.0 .0025 .0025;.0015 .0025 .0025 .0015],"","","",String[])
right=SonnetPolygon(:sheet,0,-1,2,[.0035 .006 .006 .0035;.0015 .0015 .0025 .0025],"","","",String[])
ports=[SonnetPortSpec(:box,1,0,1,["1","50","0","0","0","0","2"],SonnetRecord[]),
    SonnetPortSpec(:box,2,1,2,["2","50","0","0","0","6","2"],SonnetRecord[])]
component=[records(["TYPE","SPARAM","2"]),records(["GNDREF","FLOAT"]),
    records(["TERMW","FEED"]),records(["SMDP","0","2.5","2","L","3","1"]),
    records(["SMDP","0","3.5","2","R","4","2"])]
p=SonnetProject("float_file.son",Dict("LNG"=>"MM","CAP"=>"PF","IND"=>"NH"),.001,1e9,
    ["1","6","4","24","16","20","0"],[[".5","1","1","0","0","0"],
    [".5","1","1","0","0","0"]],Vector{String}[],["PEC","0","RES","0"],
    ["PEC","0","RES","0"],[left,right],ports,Dict{String,String}(),[component],SonnetRecord[],SonnetRecord[])

# Reactive, non-symmetric 2-port model response per frequency.
function resp(p,c,f)
    s=1im*f/1e8
    m=ComplexF64[0.1+0.02im*s 0.85-0.05im*s;0.80-0.06im*s 0.15+0.03im*s]
    (response=m,format=:s,z0=fill(50.0+0im,2))
end

freqs=[1e8,1.5e8]
outdir=@__DIR__
sols=[solve_sonnet_project(p,f;raw=true,component_response=resp,mx=36,my=24) for f in freqs]
model=sonnet_floating_model(p,1e8;component_response=resp)

pairs=model.source_terminals
model_el=model.circuit.elements[1]
ext=model.circuit.ports

# collect floating nodes needing DC-bleed paths
connnodes=Set{Int}()
for (a,b) in Iterators.flatten((pairs,model_el.terminals,ext))
    a>0 && push!(connnodes,a); b>0 && push!(connnodes,b)
end
# union-find to detect the floating island (any node not reaching 0)
parent=Dict{Int,Int}(n=>n for n in connnodes);parent[0]=0
function findroot(n)
    while parent[n]!=n;n=parent[n];end
    return n
end
function joinset(a,b)
    ra,rb=findroot(a),findroot(b);ra==rb && return;parent[max(ra,rb)]=min(ra,rb)
end
for (a,b) in Iterators.flatten((pairs,model_el.terminals,ext))
    if a>0 && b>0; joinset(a,b); elseif a>0; joinset(a,0); elseif b>0; joinset(b,0); end
end
floating=[n for n in sort(collect(connnodes)) if findroot(n)!=findroot(0)]

function emit_model(io,name,n,Ss)
    q=length(Ss)
    println(io,".MODEL $name SP N=$n FSTART=$(freqs[1]) FSTOP=$(freqs[end]) VALTYPE=CARTESIAN MATRIX=NONSYMMETRIC")
    println(io,"+ DATA=[ $q")
    for S in Ss
        for i in 1:n
            row=join((repr(real(S[i,j]))*" "*repr(imag(S[i,j])) for j in 1:n),"  ")
            println(io,"+ $row")
        end
    end
    println(io,"+ ]")
end

open(joinpath(outdir,"attach.sp"),"w") do io
    println(io,"* FLOAT file-model attach-law coupon (generated by gen.jl)")
    for (k,(a,b)) in enumerate(ext)
        println(io,"RPort$k $a $b PORTNUM=$k RZ=50 IZ=0")
        println(io,".PORT $a $b $k RPort$k")
    end
    se=join(("$a $b" for (a,b) in pairs)," ")
    println(io,"SE $se MNAME=emmod")
    sm=join(("$a $b" for (a,b) in model_el.terminals)," ")
    println(io,"SM $sm MNAME=dev")
    for n in floating
        println(io,"Rb$n $n 0 1e9")
    end
    emit_model(io,"emmod",length(pairs),[r.em.s for r in sols])
    emit_model(io,"dev",length(model_el.terminals),[resp(nothing,nothing,f).response for f in freqs])
    println(io,".LNA POI $(length(freqs)) $(join(freqs,' ')) flag='LNA'")
    prints=join(("S($i,$j)" for i in 1:length(ext),j in 1:length(ext))," ")
    println(io,".print LNA $prints")
    println(io,".end")
end
open(joinpath(outdir,"expected.txt"),"w") do io
    for (f,r) in zip(freqs,sols)
        println(io,f)
        for i in 1:2,j in 1:2; println(io,r.s[i,j]); end
    end
end
# Stored block matrices for the replay-side drift gate.
function emit_blocks(path,Ss)
    open(path,"w") do io
        for (f,S) in zip(freqs,Ss)
            println(io,f)
            for i in axes(S,1),j in axes(S,2); println(io,"$i $j $(real(S[i,j])) $(imag(S[i,j]))");end
        end
    end
end
emit_blocks(joinpath(outdir,"em_s.txt"),[r.em.s for r in sols])
emit_blocks(joinpath(outdir,"dev_s.txt"),[resp(nothing,nothing,f).response for f in freqs])
open(joinpath(outdir,"topology.txt"),"w") do io
    println(io,"nnodes ",model.circuit.nnodes)
    println(io,"source_terminals ",repr(collect(model.source_terminals)))
    println(io,"model_terminals ",repr(collect(model_el.terminals)))
    println(io,"external ",repr(collect(ext)))
    println(io,"external_z0 ",repr(collect(model.circuit.z0)))
end
@info "nodes" nnodes=model.circuit.nnodes floating external=ext
@info "written" joinpath(outdir,"attach.sp")
